        fireEvent.click(screen.getByRole('button', { name: 'Command details: npm test' }))

        expect(screen.queryByText(/Exit code:/u)).not.toBeInTheDocument()
        expect(screen.queryByText(/Duration:/u)).not.toBeInTheDocument()
    })

