        expect(first.closest('.mdxeditor-content')?.querySelectorAll('p')).toHaveLength(2)
    })

    it('updates a started command in place when completion arrives', () => {
        const started: AgentConversationEvent = {
            command: 'npm test',
            content: '',
            id: 'command-started',
            providerItemId: 'command-1',
            sequence: 2,
            status: 'inProgress',
